$dataSet->id.':'.($this->isRow ? $row->k : $col->k); $result[$id][$formula->d] = $value; if (isset($formula->a)) { foreach ($formula->a as $a) { $value = $dataSet->getCellValue( $this->isRow ? $colsOfName[ isset($a->s->b) ? $a->s->b : $a->s ][0] : $col, $this->isRow ? $row : $rowsOfName[ isset($a->s->b) ? $a->s->b : $a->s ][0] ); $result[$id][$a->d] = $value; } } } else { $result[] = $value; } } } } } } return $result; } private function formula ($formula) { $index = 0; return $this->expression($formula, $index, 0); } private function operand ($operand) { if ($this->isCheck) { if (is_object($operand)) { $res = $this->range($operand); return $res; } if (is_array($operand)) { $this->result .= '('; $res = $this->formula($operand); $this->result .= ') '; $this->isPrevOperand = true; return $res; } $this->result .= ($operand ? $operand : '0').' '; return $operand; } else { if (is_object($operand)) { return $this->range($operand); } if (is_array($operand)) { return $this->formula($operand); } return $operand; } } private function range ($range) { if (isset($range->p)) { return $this->func($range); } $values = $this->rangeValues($range); if ($this->isFill) { return $values; } $res = null; if (isset($range->a)) { switch ($range->a) { case 'min': $res = $this->min($values); break; case 'max': $res = $this->max($values); break; case 'avg': $res = $this->avg($values); break; } } else { $res = $this->sum($values); } $this->result .= ($res ? $res : '0').' '; $this->isPrevOperand = true; return $res; } private function func ($range) { switch ($range->p) { case 'нет_таблицы': $res = !isset(Engine::$params->dataSetsOfName[$range->a1]); if ($this->isCheck && $res) { $this->result .= "нет_таблицы({$range->a1}) "; $this->isPrevOperand = true; } return $res; case 'есть_таблица': $res = isset(Engine::$params->dataSetsOfName[$range->a1]); if ($this->isCheck && $res) { $this->result .= "есть_таблица({$range->a1}) "; $this->isPrevOperand = true; } return $res; } return null; } private function operation ($a, $op, $b, $isFill = false) { if ($isFill) { $d = $this->formula->d; if (is_array($a)) { if (is_array($b)) { foreach($b as $id => $bRow) { if (!isset($a[$id])) { $a[$id] = $bRow; $a[$id][$d] = null; } $a[$id][$d] = $this->operation($a[$id][$d], $op, $bRow[$d]); } } else { foreach($a as &$aRow) { $aRow[$d] = $this->operation($aRow[$d], $op, $b); } } return $a; } else if (is_array($b)) { foreach($b as &$bRow) { $bRow[$d] = $this->operation($a, $op, $bRow[$d]); } return $b; } } $a = isset($a) ? $a : 0; $b = isset($b) ? $b : 0; try { switch ($op) { case '+': return correctFloat($a + $b); case '-': return correctFloat($a - $b); case '*': return correctFloat($a * $b); case '/': return $b ? correctFloat($a / $b) : 0; case '==': return $a == $b; case '!=': return $a != $b; case '>=': return $a >= $b; case '<=': return $a <= $b; case '>': return $a > $b; case '<': return $a < $b; case '&&': return $a && $b; case '||': return $a || $b; case '<<': return $a . $b; } } catch (Throwable $e) {} return 0; } private function expression ($formula, &$index, $leftPriority) { $left = $this->operand($formula[$index++]); $count = count($formula); while($index < $count) { $op = $formula[$index]; if (($op === '&&' && !$left) || ($op === '||' && $left)) { break; } $curPriority = self::$priority[$op]; if ($index + 1 >= $count || $leftPriority >= $curPriority) { break; } if ($this->isCheck && $this->isPrevOperand) { $this->result .= self::$operationsForUser[$op].' '; $this->isPrevOperand = false; } if ($index + 3 < $count && self::$priority[$formula[$index + 2]] > $curPriority) { ++$index; if ($this->isCheck) { $saveResult = $this->result; $this->result = ''; $right = $this->expression($formula, $index, $curPriority); $this->result = $saveResult.$this->result; } else { $right = $this->expression($formula, $index, $curPriority); } } else { $right = $this->operand($formula[++$index]); ++$index; } $left = $this->operation($left, $op, $right, isset($this->isFill)); } return $left; } private function sum ($values) { $r = null; $cnt = count($values); if ($cnt > 0) { $r = $values[0]; for ($i = 1; $i < $cnt; $i++) { try { $r = correctFloat($r + $values[$i]); } catch (Throwable $e) {} } } return $r; } private function min ($values) { $r = null; $cnt = count($values); if ($cnt > 0) { $r = $values[0]; for ($i = 1; $i < $cnt; $i++) { $v = $values[$i]; if ($v < $r) { $r = $v; } } } return $r; } private function max ($values) { $r = null; $cnt = count($values); if ($cnt > 0) { $r = $values[0]; for ($i = 1; $i < $cnt; $i++) { $v = $values[$i]; if ($v > $r) { $r = $v; } } } return $r; } private function avg ($values) { $r = 0; $cnt = count($values); if ($cnt > 0) { foreach ($values as $v) { try { $r = correctFloat($r + $v); } catch (Throwable $e) {} } try { $r = correctFloat($r / $cnt); } catch (Throwable $e) {} } return $r; } private static $priority = [ '*' => 4, '/' => 4, '+' => 3, '-' => 3, '<<' => 3, '==' => 2, '!=' => 2, '<' => 2, '<=' => 2, '>' => 2, '>=' => 2, '&&' => 1, '||' => 1 ]; private static $operationsForUser = [ '*' => '*', '/' => '/', '+' => '+', '-' => '-', '<<' => '+', '==' => '=', '!=' => '<>', '<' => '<', '<=' => '<=', '>' => '>', '>=' => '>=', '&&' => 'И', '||' => 'ИЛИ' ]; } 